example.code:
#include <iostream>

class Circle {
public:
    double radius;

    Circle() {
        radius = 1.0;
    }

    Circle(double newRadius) {
        radius = newRadius;
    }

    double getArea() const {
        return radius * radius * 3.14159;
    }
};

int main() {
    // 1. Named object creation and memberwise copy
    Circle circle1;
    Circle circle2(5.0);

    std::cout << "circle1 radius: " << circle1.radius << "\n";
    std::cout << "circle2 radius: " << circle2.radius << "\n";

    circle1 = circle2; // Memberwise copy: circle2's radius is copied to circle1
    std::cout << "After circle1 = circle2, circle1 radius: " << circle1.radius << "\n";

    // 2. Memory size verification: member functions add 0 bytes to instances
    std::cout << "Size of circle1: " << sizeof(circle1) << " bytes\n";
    std::cout << "Size of circle2: " << sizeof(circle2) << " bytes\n";

    // 3. Anonymous object evaluation
    std::cout << "Anonymous circle default area: " << Circle().getArea() << "\n";
    std::cout << "Anonymous circle radius 8 area: " << Circle(8.0).getArea() << "\n";

    // 4. Copy-initialization via anonymous object (Check Point 9.9)
    Circle circle3 = Circle();
    std::cout << "circle3 radius: " << circle3.radius << "\n";

    return 0;
}

#include <iostream>

// =========================================
// Interface declaration (equivalent to Circle.h)
// =========================================
class Circle {
public:
    double radius;

    Circle();
    Circle(double newRadius);
    double getArea() const;
}; // Trailing semicolon is mandatory!

// =========================================
// Implementation code (equivalent to Circle.cpp)
// =========================================
// Scope resolution operator :: associates constructor with Circle
Circle::Circle() {
    radius = 1.0;
}

Circle::Circle(double newRadius) {
    radius = newRadius;
}

// Scope resolution operator :: associates getArea with Circle
double Circle::getArea() const {
    return radius * radius * 3.14159;
}

// =========================================
// Client program (equivalent to TestCircleWithHeader.cpp)
// =========================================
int main() {
    Circle circle1;
    Circle circle2(5.0);

    std::cout << "The area of the circle of radius "
              << circle1.radius << " is " << circle1.getArea() << "\n";
    std::cout << "The area of the circle of radius "
              << circle2.radius << " is " << circle2.getArea() << "\n";

    // Modify circle radius
    circle2.radius = 100.0;
    std::cout << "The area of the circle of radius "
              << circle2.radius << " is " << circle2.getArea() << "\n";

    return 0;
}
